INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('shift the paradigm', '改變範式；轉變思維框架', 'to fundamentally change the way something is understood or done', '[{"en":"Cloud computing shifted the paradigm for enterprise software.","zh-TW":"雲計算改變了企業軟體的範式。"},{"en":"Our research aims to shift the paradigm on customer loyalty.","zh-TW":"我們的研究旨在改變客戶忠誠度的思維框架。"}]', 'expression'),
('short-list', '列入候選名單；入圍', 'to reduce a list of applicants or options to only the most suitable few', '[{"en":"We short-listed five vendors for the final evaluation.","zh-TW":"我們將五個供應商列入了最終評估的候選名單。"},{"en":"Short-list based on both technical fit and culture alignment.","zh-TW":"根據技術契合度和文化一致性進行入圍篩選。"}]', 'phrasal verb'),
('silent majority', '沉默的多數；無聲的大多數', 'the large group of people who hold a view but rarely express it publicly', '[{"en":"The silent majority supported the change but didn''t speak up.","zh-TW":"沉默的多數支持這個改變但沒有發言。"},{"en":"Seek input from the silent majority through anonymous surveys.","zh-TW":"通過匿名調查徵求沉默多數的意見。"}]', 'expression'),
('single source of truth', '唯一可信來源；統一數據來源', 'a central repository that holds the most accurate and up-to-date version of data', '[{"en":"We built a single source of truth for all customer data.","zh-TW":"我們建立了所有客戶數據的唯一可信來源。"},{"en":"A single source of truth prevents data inconsistency.","zh-TW":"統一數據來源防止了數據不一致。"}]', 'business idiom'),
('six sigma', '六西格瑪；品質管理方法', 'a data-driven quality improvement methodology aimed at reducing defects', '[{"en":"Six sigma reduced our defect rate to near zero.","zh-TW":"六西格瑪將我們的缺陷率降低到近乎零。"},{"en":"Six sigma principles guide our manufacturing quality processes.","zh-TW":"六西格瑪原則指導著我們的製造品質流程。"}]', 'business idiom'),
('skill gap', '技能差距；能力缺口', 'the difference between the skills required for a job and those actually held by employees', '[{"en":"We conducted a survey to identify skill gaps across departments.","zh-TW":"我們進行了調查以識別各部門的技能差距。"},{"en":"Addressing the skill gap is a priority for HR this year.","zh-TW":"解決技能差距是人力資源部門今年的優先事項。"}]', 'business idiom'),
('slow burn', '緩慢發展；慢熱效應', 'a situation that develops gradually over a long period before becoming significant', '[{"en":"The product was a slow burn — it took two years to gain traction.","zh-TW":"該產品是慢熱型的——花了兩年時間才取得進展。"},{"en":"Regulatory approvals can create a slow burn for new industries.","zh-TW":"監管審批可能為新行業帶來緩慢發展的效應。"}]', 'expression'),
('smart goals', 'SMART目標；具體可衡量的目標', 'goals that are Specific, Measurable, Achievable, Relevant, and Time-bound', '[{"en":"Set smart goals so employees know exactly what is expected.","zh-TW":"設定SMART目標讓員工確切知道期望是什麼。"},{"en":"Smart goals improve focus and accountability.","zh-TW":"具體可衡量的目標提高了專注度和問責制。"}]', 'business idiom'),
('soft close', '軟性成交；溫和收尾', 'a gentle way of asking for a buying decision without pressure', '[{"en":"A soft close like \"Does this solution look right to you?\" builds trust.","zh-TW":"像\"這個解決方案看起來適合您嗎？\"這樣的軟性成交建立了信任。"},{"en":"Use a soft close when the prospect needs more time.","zh-TW":"當潛在客戶需要更多時間時使用軟性成交方式。"}]', 'business idiom'),
('solution selling', '解決方案銷售；顧問式銷售', 'a sales methodology focused on identifying customer problems and offering tailored solutions', '[{"en":"Solution selling requires deep understanding of the customer''s challenges.","zh-TW":"解決方案銷售需要對客戶挑戰的深刻理解。"},{"en":"We train our sales team in solution selling techniques.","zh-TW":"我們對銷售團隊進行解決方案銷售技術的培訓。"}]', 'business idiom'),
('speak truth to power', '對掌權者說真話；勇於諫言', 'to tell the truth or challenge those in authority even when it is uncomfortable', '[{"en":"A good advisor must be willing to speak truth to power.","zh-TW":"好的顧問必須願意對掌權者說真話。"},{"en":"Speaking truth to power is how organizations avoid blind spots.","zh-TW":"對掌權者說真話是組織避免盲點的方式。"}]', 'expression'),
('stand one''s ground', '堅持立場；不退讓', 'to maintain one''s position or argument despite pressure to change', '[{"en":"Stand your ground when negotiating key contract terms.","zh-TW":"在談判關鍵合同條款時堅持立場。"},{"en":"She stood her ground against pressure to cut the budget.","zh-TW":"她在削減預算的壓力下堅持了立場。"}]', 'expression'),
('strategic initiative', '戰略舉措；重大戰略行動', 'a specific high-priority action designed to achieve a strategic objective', '[{"en":"Cost reduction is our primary strategic initiative this year.","zh-TW":"降低成本是我們今年的主要戰略舉措。"},{"en":"Each strategic initiative has a dedicated owner and timeline.","zh-TW":"每個戰略舉措都有專門的負責人和時間表。"}]', 'business idiom'),
('strategic sourcing', '戰略採購', 'a procurement approach focused on optimizing value from supplier relationships', '[{"en":"Strategic sourcing reduced our supply costs by 18%.","zh-TW":"戰略採購將我們的供應成本降低了18%。"},{"en":"Strategic sourcing evaluates quality, price, and reliability.","zh-TW":"戰略採購評估品質、價格和可靠性。"}]', 'business idiom'),
('stretch target', '延伸目標；挑戰性目標', 'an ambitious goal set beyond what is considered easily achievable to motivate higher performance', '[{"en":"The stretch target of 200% growth pushed the team to innovate.","zh-TW":"200%增長的延伸目標推動了團隊創新。"},{"en":"Stretch targets foster a growth mindset when framed correctly.","zh-TW":"當框架正確時延伸目標培養了成長心態。"}]', 'business idiom'),
('sunk cost', '沉沒成本', 'money or resources already spent that cannot be recovered, and should not influence future decisions', '[{"en":"Don''t let sunk costs drive the decision to continue a failing project.","zh-TW":"不要讓沉沒成本驅動繼續失敗項目的決定。"},{"en":"Sunk cost thinking keeps organizations stuck in bad investments.","zh-TW":"沉沒成本思維使組織陷入糟糕的投資。"}]', 'business idiom'),
('sustainability reporting', '永續報告；可持續性報告', 'corporate disclosure of environmental, social, and governance performance metrics', '[{"en":"Sustainability reporting is now required by major investors.","zh-TW":"永續報告現已被主要投資者所要求。"},{"en":"Our sustainability reporting follows GRI standards.","zh-TW":"我們的永續報告遵循GRI標準。"}]', 'business idiom'),
('switch gears', '換個話題；轉換方向', 'to change the focus or direction of a conversation or activity', '[{"en":"Let''s switch gears and discuss the Q4 launch plan.","zh-TW":"讓我們換個話題討論第四季度的啟動計劃。"},{"en":"The team switched gears mid-project when priorities changed.","zh-TW":"當優先事項改變時團隊在項目中途轉換了方向。"}]', 'expression'),
('synergy effect', '協同效應', 'the additional value created when two or more entities work together beyond their individual capacities', '[{"en":"The merger created a synergy effect in combined R&D operations.","zh-TW":"合并在聯合研發業務中創造了協同效應。"},{"en":"Synergy effects can take time to materialize after acquisition.","zh-TW":"協同效應在收購後可能需要時間才能實現。"}]', 'business idiom'),
('take a calculated risk', '承擔經過計算的風險；謹慎冒險', 'to deliberately accept a risk after evaluating the potential benefits and downsides', '[{"en":"We took a calculated risk by entering the emerging market early.","zh-TW":"我們謹慎冒險提早進入了新興市場。"},{"en":"Taking a calculated risk is different from reckless gambling.","zh-TW":"承擔經過計算的風險不同於魯莽賭博。"}]', 'expression'),
('target demographic', '目標人口統計；目標客群', 'the specific segment of the population a product or service is aimed at', '[{"en":"Define your target demographic before designing the campaign.","zh-TW":"在設計活動之前定義您的目標客群。"},{"en":"Our target demographic is professionals aged 25 to 40.","zh-TW":"我們的目標客群是25至40歲的專業人士。"}]', 'business idiom'),
('tear down silos', '打破部門壁壘；消除孤立', 'to break down barriers between departments that prevent information sharing and collaboration', '[{"en":"Our new CRM helps tear down silos between sales and marketing.","zh-TW":"我們的新CRM有助於打破銷售和行銷之間的壁壘。"},{"en":"Leadership must model cross-functional behavior to tear down silos.","zh-TW":"領導層必須以跨職能行為來消除孤立。"}]', 'expression'),
('thought experiment', '思想實驗；假設性思考', 'a hypothetical scenario used to explore ideas and their implications', '[{"en":"Let''s run a thought experiment: what if we doubled prices?","zh-TW":"讓我們進行一個思想實驗：如果我們把價格翻倍呢？"},{"en":"A thought experiment can reveal unexpected strategic options.","zh-TW":"思想實驗可以揭示意想不到的戰略選擇。"}]', 'expression'),
('through the lens of', '從…的角度；透過…的視角', 'viewing or evaluating something from a particular perspective or framework', '[{"en":"Evaluate the decision through the lens of customer value.","zh-TW":"從客戶價值的角度評估這個決定。"},{"en":"Through the lens of sustainability the choice is clear.","zh-TW":"從可持續性的視角來看選擇是明確的。"}]', 'prepositional phrase'),
('tier-one supplier', '一級供應商', 'a supplier that sells directly to the final manufacturer or company', '[{"en":"Tier-one suppliers must meet our quality and delivery standards.","zh-TW":"一級供應商必須達到我們的品質和交付標準。"},{"en":"We consolidated to fewer tier-one suppliers for better control.","zh-TW":"我們整合成較少的一級供應商以獲得更好的控制。"}]', 'business idiom'),
('trade-off analysis', '權衡分析；取捨分析', 'evaluating the costs and benefits of different options to find the best compromise', '[{"en":"A trade-off analysis showed cost and speed favor option B.","zh-TW":"權衡分析顯示成本和速度方面選項B更優。"},{"en":"Trade-off analysis helps teams make transparent decisions.","zh-TW":"取捨分析有助於團隊做出透明的決定。"}]', 'business idiom'),
('trigger point', '觸發點；臨界點', 'a specific event or condition that causes a process or reaction to begin', '[{"en":"The discount email was the trigger point for the purchase surge.","zh-TW":"折扣電子郵件是購買激增的觸發點。"},{"en":"Know the trigger points that move prospects from interest to action.","zh-TW":"了解將潛在客戶從興趣轉變為行動的觸發點。"}]', 'expression'),
('turn the corner', '轉機；渡過難關', 'to reach a point where a difficult situation begins to improve', '[{"en":"After two tough quarters we finally turned the corner.","zh-TW":"在兩個艱難的季度後我們終於迎來了轉機。"},{"en":"Turning the corner requires persistent effort and adaptability.","zh-TW":"渡過難關需要持續的努力和適應性。"}]', 'expression'),
('under contract', '在合約約束下；已簽合約', 'bound by the terms of a legal agreement', '[{"en":"The supplier is under contract until the end of the year.","zh-TW":"供應商在合約約束下直到年底。"},{"en":"Ensure all freelancers are under contract before work begins.","zh-TW":"確保所有自由職業者在工作開始前已簽合約。"}]', 'prepositional phrase'),
('unique selling point', '獨特賣點；核心競爭優勢', 'the feature or benefit that distinguishes a product or service from competitors', '[{"en":"Our unique selling point is same-day delivery anywhere in the city.","zh-TW":"我們的獨特賣點是城市任何地方的當天送達。"},{"en":"Know your unique selling point before entering a competitive pitch.","zh-TW":"在進行競爭性推介之前了解您的核心競爭優勢。"}]', 'business idiom'),
('up to speed', '了解情況；跟上進度', 'having the latest information or being current with developments', '[{"en":"Bring the new manager up to speed on the current project status.","zh-TW":"讓新經理了解當前項目的狀況。"},{"en":"A clear onboarding plan gets employees up to speed faster.","zh-TW":"清晰的入職計劃讓員工更快地跟上進度。"}]', 'prepositional phrase'),
('upstream process', '上游流程', 'earlier stages in a workflow or supply chain that feed into downstream activities', '[{"en":"Fixing the upstream process eliminated delays at assembly.","zh-TW":"改善上游流程消除了組裝階段的延誤。"},{"en":"Issues in the upstream process cascade into delivery problems.","zh-TW":"上游流程中的問題會波及到交付問題。"}]', 'business idiom'),
('user journey', '用戶旅程', 'the complete sequence of steps a user takes when interacting with a product or service', '[{"en":"Mapping the user journey revealed friction at checkout.","zh-TW":"繪製用戶旅程揭示了結帳時的摩擦點。"},{"en":"Optimize the user journey to reduce drop-off at each stage.","zh-TW":"優化用戶旅程以減少每個階段的流失。"}]', 'business idiom'),
('value creation', '價值創造', 'the process of delivering products or services that benefit customers and generate returns', '[{"en":"Our strategy centers on value creation for long-term shareholders.","zh-TW":"我們的策略以為長期股東創造價值為中心。"},{"en":"Value creation is the foundation of sustainable business.","zh-TW":"價值創造是可持續業務的基礎。"}]', 'business idiom'),
('velocity of change', '變化速度；改變的快慢', 'the speed at which change is occurring in an industry or organization', '[{"en":"The velocity of change in AI requires continuous learning.","zh-TW":"人工智慧領域的變化速度要求持續學習。"},{"en":"Organizations must increase agility to match the velocity of change.","zh-TW":"組織必須提高靈活性以跟上變化速度。"}]', 'expression'),
('vested interest', '既得利益；切身利益', 'a personal stake in an outcome, often influencing one''s objectivity', '[{"en":"Investors have a vested interest in the success of the merger.","zh-TW":"投資者對合並的成功有切身利益。"},{"en":"Acknowledge vested interests when presenting proposals.","zh-TW":"在提交提案時承認切身利益。"}]', 'expression'),
('vision statement', '願景宣言；企業願景', 'a brief aspirational description of what an organization hopes to achieve in the future', '[{"en":"Our vision statement guides every strategic decision we make.","zh-TW":"我們的願景宣言指導著我們做出的每一個戰略決策。"},{"en":"Align the team around the vision statement during planning.","zh-TW":"在規劃期間讓團隊圍繞企業願景保持一致。"}]', 'business idiom'),
('walk away from the table', '退出談判；離開談判桌', 'to leave a negotiation without reaching an agreement', '[{"en":"Know your minimum acceptable terms before you walk away from the table.","zh-TW":"在退出談判之前了解您的最低可接受條款。"},{"en":"Walking away from the table reset the dynamic in our favor.","zh-TW":"退出談判重置了有利於我們的談判動態。"}]', 'expression'),
('waste reduction', '減少浪費；廢棄物減量', 'the process of eliminating unnecessary use of resources, time, or materials', '[{"en":"Lean methods achieved significant waste reduction in our factory.","zh-TW":"精益方法在我們的工廠實現了顯著的廢棄物減量。"},{"en":"Waste reduction initiatives cut operating costs by 12%.","zh-TW":"減少浪費舉措將運營成本降低了12%。"}]', 'business idiom'),
('win-win outcome', '雙贏結果', 'a result that is beneficial for all parties involved', '[{"en":"A win-win outcome builds long-term relationships.","zh-TW":"雙贏結果建立了長期關係。"},{"en":"Seek a win-win outcome rather than maximizing at the other side''s expense.","zh-TW":"尋求雙贏結果而不是以犧牲另一方為代價最大化利益。"}]', 'expression'),
('workforce optimization', '勞動力優化；人力資源最佳化', 'aligning staff skills, schedules, and workloads to maximize productivity and efficiency', '[{"en":"Workforce optimization tools reduced overtime costs by 20%.","zh-TW":"勞動力優化工具將加班成本降低了20%。"},{"en":"Workforce optimization aligns headcount with business demand.","zh-TW":"人力資源最佳化將員工人數與業務需求相對應。"}]', 'business idiom'),
('year-over-year growth', '年同比增長；逐年增長', 'the comparison of a period''s performance with the same period in the previous year', '[{"en":"We posted 22% year-over-year growth in recurring revenue.","zh-TW":"我們的經常性收入實現了22%的年同比增長。"},{"en":"Year-over-year growth metrics matter more than month-to-month changes.","zh-TW":"年同比增長指標比月度變化更重要。"}]', 'business idiom'),
('yield to pressure', '屈服於壓力；讓步', 'to give in to demands or pressure from others', '[{"en":"Don''t yield to pressure when you know the terms are unacceptable.","zh-TW":"當您知道條款不可接受時不要屈服於壓力。"},{"en":"Yielding to pressure early sets a bad precedent.","zh-TW":"過早讓步設定了不好的先例。"}]', 'expression'),
('allocate resources', '分配資源', 'to distribute available resources such as money, time, or staff to various activities', '[{"en":"Allocate resources based on strategic impact, not seniority.","zh-TW":"根據戰略影響而不是資歷分配資源。"},{"en":"We need to allocate resources more effectively across teams.","zh-TW":"我們需要更有效地在各團隊之間分配資源。"}]', 'phrasal verb'),
('assess the damage', '評估損失；了解損害程度', 'to evaluate the negative consequences of a bad event or decision', '[{"en":"After the data breach we quickly moved to assess the damage.","zh-TW":"數據洩露後我們迅速開始評估損失。"},{"en":"Assessing the damage is the first step in any crisis response.","zh-TW":"評估損失是任何危機應對的第一步。"}]', 'expression'),
('baseline measurement', '基準測量；基線衡量', 'an initial data point used as a reference for measuring future progress', '[{"en":"Establish a baseline measurement before implementing any change.","zh-TW":"在實施任何更改之前建立基準測量。"},{"en":"Without a baseline measurement it is impossible to gauge improvement.","zh-TW":"沒有基線衡量就無法衡量改進。"}]', 'business idiom'),
('basis points', '基點', 'a unit of measure equal to one hundredth of a percentage point, used in finance', '[{"en":"The central bank raised rates by 25 basis points.","zh-TW":"央行將利率提高了25個基點。"},{"en":"A rise of 50 basis points significantly increases borrowing costs.","zh-TW":"上升50個基點顯著增加了借貸成本。"}]', 'business idiom'),
('below the line', '非常規行銷；線下行銷', 'marketing activities targeted at specific individuals rather than mass audiences', '[{"en":"Below the line campaigns like direct mail drove strong conversions.","zh-TW":"直郵等線下行銷活動帶動了強勁的轉化率。"},{"en":"Below the line activities allow for personalized messaging.","zh-TW":"線下行銷活動允許個性化訊息傳遞。"}]', 'business idiom'),
('bid and tender', '競標；投標', 'the process of submitting competitive proposals to win a contract or project', '[{"en":"We won the government bid and tender for infrastructure services.","zh-TW":"我們贏得了基礎設施服務的政府競標。"},{"en":"The bid and tender process required detailed cost breakdowns.","zh-TW":"競標過程需要詳細的成本明細。"}]', 'business idiom'),
('brand loyalty', '品牌忠誠度', 'the tendency of consumers to continue buying a particular brand over alternatives', '[{"en":"Brand loyalty reduces customer acquisition costs over time.","zh-TW":"品牌忠誠度隨著時間的推移降低了客戶獲取成本。"},{"en":"Reward programs are one of the best tools for building brand loyalty.","zh-TW":"獎勵計劃是建立品牌忠誠度的最佳工具之一。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('breakeven analysis', '損益平衡分析；盈虧平衡分析', 'the calculation of the point at which revenue equals costs and no profit or loss is made', '[{"en":"Breakeven analysis showed profitability within 18 months.","zh-TW":"損益平衡分析顯示18個月內可盈利。"},{"en":"Run a breakeven analysis before approving capital expenditure.","zh-TW":"在批准資本支出之前進行損益平衡分析。"}]', 'business idiom'),
('bridge the communication gap', '彌合溝通差距', 'to improve understanding and exchange between people or groups with different communication styles', '[{"en":"A liaison role helps bridge the communication gap between tech and business.","zh-TW":"聯絡角色幫助彌合技術和業務之間的溝通差距。"},{"en":"Regular cross-team meetings bridge the communication gap.","zh-TW":"定期的跨團隊會議彌合了溝通差距。"}]', 'expression'),
('build trust', '建立信任', 'to develop confidence and credibility in a relationship over time through consistent actions', '[{"en":"Consistent delivery is the fastest way to build trust with clients.","zh-TW":"一致的交付是與客戶建立信任最快的方式。"},{"en":"It takes years to build trust and seconds to destroy it.","zh-TW":"建立信任需要多年，摧毀它只需幾秒。"}]', 'phrasal verb'),
('business continuity plan', '業務持續計劃；緊急應變計劃', 'a strategy ensuring essential functions can continue during and after a disaster or disruption', '[{"en":"We tested our business continuity plan through simulation exercises.","zh-TW":"我們通過模擬演練測試了業務持續計劃。"},{"en":"Every department must have a business continuity plan in place.","zh-TW":"每個部門都必須有業務持續計劃。"}]', 'business idiom'),
('calibrate expectations', '校準預期；調整期望', 'to align what is expected with what is realistically possible', '[{"en":"Calibrate expectations at the start of every client engagement.","zh-TW":"在每次客戶合作開始時校準預期。"},{"en":"Underpromising and overdelivering is one way to calibrate expectations.","zh-TW":"承諾少但交付多是校準預期的一種方式。"}]', 'expression'),
('capitalize on trends', '利用趨勢；把握趨勢機會', 'to use emerging trends as an opportunity to grow or gain advantage', '[{"en":"Companies that capitalized on the remote work trend grew rapidly.","zh-TW":"利用遠程辦公趨勢的公司迅速成長。"},{"en":"Capitalize on sustainability trends to attract new customers.","zh-TW":"利用可持續性趨勢吸引新客戶。"}]', 'phrasal verb'),
('carry out due diligence', '進行盡職調查', 'to thoroughly research and verify facts before making a decision or investment', '[{"en":"We carry out due diligence on every potential acquisition target.","zh-TW":"我們對每個潛在的收購目標進行盡職調查。"},{"en":"Carry out due diligence before committing to a new vendor.","zh-TW":"在與新供應商合作前進行盡職調查。"}]', 'expression'),
('change management strategy', '變革管理策略', 'a structured approach for transitioning individuals and organizations to a desired future state', '[{"en":"A solid change management strategy ensures employee adoption.","zh-TW":"健全的變革管理策略確保員工採納。"},{"en":"Communication is the cornerstone of any change management strategy.","zh-TW":"溝通是任何變革管理策略的基石。"}]', 'business idiom'),
('co-invest', '共同投資；聯合投資', 'to invest jointly with another party, sharing both risk and potential returns', '[{"en":"We co-invested with the local partner to enter the Asian market.","zh-TW":"我們與當地合作夥伴共同投資進入了亞洲市場。"},{"en":"Co-investing reduces individual exposure to market risk.","zh-TW":"共同投資降低了個別投資者的市場風險敞口。"}]', 'phrasal verb'),
('competitive benchmarking', '競爭基準分析', 'evaluating your performance against that of direct competitors to identify gaps', '[{"en":"Competitive benchmarking revealed we lag behind in customer onboarding speed.","zh-TW":"競爭基準分析顯示我們在客戶入職速度上落後。"},{"en":"Competitive benchmarking should inform your product roadmap.","zh-TW":"競爭基準分析應該影響您的產品路線圖。"}]', 'business idiom'),
('contingency budget', '應急預算；備用預算', 'a reserve of funds set aside for unexpected expenses or emergencies', '[{"en":"Include a 10% contingency budget in all project plans.","zh-TW":"在所有項目計劃中納入10%的應急預算。"},{"en":"The contingency budget covered the unplanned equipment repair.","zh-TW":"應急預算涵蓋了計劃外的設備維修費用。"}]', 'business idiom'),
('conversion funnel', '轉化漏斗', 'the step-by-step process a prospect follows before becoming a paying customer', '[{"en":"Analyzing the conversion funnel showed a 40% drop at checkout.","zh-TW":"分析轉化漏斗顯示結帳時有40%的流失。"},{"en":"Simplify each stage of the conversion funnel to increase sign-ups.","zh-TW":"簡化轉化漏斗的每個階段以增加註冊。"}]', 'business idiom'),
('corporate culture', '企業文化；公司文化', 'the shared values, behaviors, and practices that define how an organization operates', '[{"en":"Corporate culture impacts talent retention and innovation.","zh-TW":"企業文化影響人才留存和創新。"},{"en":"The CEO sets the tone for corporate culture from the top.","zh-TW":"執行長從高層定下了企業文化的基調。"}]', 'business idiom'),
('decision-making framework', '決策框架', 'a structured approach for evaluating options and choosing among them', '[{"en":"Our decision-making framework considers cost, risk, and alignment.","zh-TW":"我們的決策框架考慮成本、風險和一致性。"},{"en":"A clear decision-making framework speeds up team consensus.","zh-TW":"清晰的決策框架加速了團隊共識。"}]', 'business idiom'),
('deliverable milestone', '可交付里程碑', 'a specific output or achievement marking a stage in a project timeline', '[{"en":"Each deliverable milestone requires sign-off before the next phase.","zh-TW":"每個可交付里程碑在進入下一階段之前需要簽署批准。"},{"en":"Track deliverable milestones in the project dashboard.","zh-TW":"在項目儀表板中跟蹤可交付里程碑。"}]', 'business idiom'),
('demand forecasting', '需求預測', 'the process of estimating future customer demand for products or services', '[{"en":"Accurate demand forecasting prevents stockouts and overstock.","zh-TW":"準確的需求預測防止缺貨和積壓。"},{"en":"We use AI-powered demand forecasting to optimize supply chains.","zh-TW":"我們使用AI驅動的需求預測優化供應鏈。"}]', 'business idiom'),
('deployment timeline', '部署時間表；上線計劃', 'the schedule for when a system, product, or plan will be launched or implemented', '[{"en":"The deployment timeline was pushed back due to testing delays.","zh-TW":"由於測試延誤部署時間表被推遲了。"},{"en":"Share the deployment timeline with all affected teams.","zh-TW":"與所有受影響的團隊分享部署時間表。"}]', 'business idiom'),
('discussion paper', '討論文件；諮詢文件', 'a document presenting ideas or proposals for discussion rather than as final decisions', '[{"en":"We circulated a discussion paper on restructuring options.","zh-TW":"我們分發了關於重組選項的討論文件。"},{"en":"The discussion paper invited feedback from all managers.","zh-TW":"討論文件邀請了所有管理人員的反饋。"}]', 'business idiom'),
('document best practices', '記錄最佳實踐', 'to write down the most effective methods or procedures for future reference', '[{"en":"Document best practices after successful campaigns.","zh-TW":"在成功的活動後記錄最佳實踐。"},{"en":"Documented best practices reduce ramp-up time for new staff.","zh-TW":"記錄的最佳實踐減少了新員工的磨合時間。"}]', 'phrasal verb'),
('due for renewal', '即將到期；需要續約', 'a contract or agreement that is approaching its expiration and needs to be renewed', '[{"en":"All annual service contracts due for renewal will be reviewed.","zh-TW":"所有即將到期的年度服務合約將被審查。"},{"en":"Reach out 90 days before a contract is due for renewal.","zh-TW":"在合約即將到期前90天聯繫客戶。"}]', 'prepositional phrase'),
('efficient allocation', '有效分配；高效配置', 'distributing resources in a way that maximizes output or value', '[{"en":"Efficient allocation of capital is the CFO''s primary responsibility.","zh-TW":"資本的有效分配是財務長的主要職責。"},{"en":"Efficient allocation requires clear visibility into demand.","zh-TW":"有效配置需要對需求有清晰的能見度。"}]', 'expression'),
('embed in the culture', '融入文化；根植於文化', 'to make a practice or value a permanent part of an organization''s way of operating', '[{"en":"We worked to embed continuous improvement in the culture.","zh-TW":"我們致力於將持續改進融入文化中。"},{"en":"Safety is embedded in the culture at every level of operations.","zh-TW":"安全在各個運營層面都根植於文化中。"}]', 'expression'),
('empower decision-making', '賦予決策權；授權決策', 'to give individuals or teams the authority and tools to make decisions on their own', '[{"en":"Empowering decision-making at the front line speeds up response times.","zh-TW":"在一線賦予決策權加快了反應時間。"},{"en":"Leaders who empower decision-making build stronger teams.","zh-TW":"授權決策的領導者建立了更強大的團隊。"}]', 'expression'),
('escalation path', '升級路徑；問題上報流程', 'the defined route through which unresolved issues are passed to higher authority', '[{"en":"Every support team must have a clear escalation path.","zh-TW":"每個支持團隊必須有清晰的問題上報流程。"},{"en":"Follow the escalation path to resolve disputes quickly.","zh-TW":"遵循升級路徑快速解決爭議。"}]', 'business idiom'),
('executive sponsorship', '高管贊助；高層支持', 'support from a senior leader who champions a project and removes obstacles', '[{"en":"Executive sponsorship was crucial to the digital transformation success.","zh-TW":"高管贊助對數字化轉型的成功至關重要。"},{"en":"Without executive sponsorship cross-functional projects stall.","zh-TW":"沒有高層支持跨職能項目會停滯不前。"}]', 'business idiom'),
('exit interview', '離職面談', 'a meeting with a departing employee to gather feedback on their experience', '[{"en":"Exit interviews provide honest insights into company culture gaps.","zh-TW":"離職面談提供了對公司文化差距的誠實見解。"},{"en":"Use exit interview data to improve retention strategies.","zh-TW":"使用離職面談數據改善留才策略。"}]', 'business idiom'),
('face-to-face meeting', '面對面會議；當面會談', 'a meeting where participants are physically present together rather than communicating remotely', '[{"en":"A face-to-face meeting built trust faster than video calls.","zh-TW":"面對面會議比視訊會議更快地建立了信任。"},{"en":"For complex negotiations a face-to-face meeting is essential.","zh-TW":"對於複雜的談判面對面會談是必要的。"}]', 'expression'),
('feedback mechanism', '反饋機制', 'a system or process for collecting and acting on feedback from stakeholders or users', '[{"en":"Our NPS survey is the primary feedback mechanism for service quality.","zh-TW":"我們的NPS調查是服務品質的主要反饋機制。"},{"en":"A strong feedback mechanism accelerates product iteration.","zh-TW":"強大的反饋機制加速了產品迭代。"}]', 'business idiom'),
('field-test', '實地測試；現場驗證', 'to test a product or process in real-world conditions before full deployment', '[{"en":"We field-tested the device in extreme temperatures before launch.","zh-TW":"我們在上市前在極端溫度下對設備進行了實地測試。"},{"en":"Field-testing revealed usability issues not found in the lab.","zh-TW":"實地測試揭示了實驗室中未發現的易用性問題。"}]', 'phrasal verb'),
('financial due diligence', '財務盡職調查', 'an in-depth review of a company''s financial records before a transaction or investment', '[{"en":"Financial due diligence uncovered significant undisclosed liabilities.","zh-TW":"財務盡職調查發現了重大未披露負債。"},{"en":"Never skip financial due diligence no matter how trusted the partner.","zh-TW":"無論合作夥伴多麼值得信任都不要跳過財務盡職調查。"}]', 'business idiom'),
('first-mover disadvantage', '先行者劣勢', 'the costs and risks borne by the first company to enter a market, which later entrants avoid', '[{"en":"First-mover disadvantage meant we spent years educating the market.","zh-TW":"先行者劣勢意味著我們花了數年時間教育市場。"},{"en":"Weigh first-mover disadvantage against the opportunity before entering early.","zh-TW":"在提早進入之前衡量先行者劣勢與機會。"}]', 'business idiom'),
('flag as a priority', '標記為優先事項；列為首要任務', 'to mark or designate something as needing immediate attention or resources', '[{"en":"Flag the delivery delay as a priority before it escalates.","zh-TW":"在問題升級之前將交付延誤標記為優先事項。"},{"en":"The compliance team flagged the audit finding as a priority.","zh-TW":"合規團隊將審計發現列為首要任務。"}]', 'expression'),
('follow-up action', '後續行動；跟進措施', 'steps taken after a meeting, discussion, or event to advance progress', '[{"en":"Document follow-up actions with owners and deadlines after every meeting.","zh-TW":"每次會議後記錄帶有負責人和截止日期的後續行動。"},{"en":"Follow-up action within 24 hours shows professionalism.","zh-TW":"24小時內的跟進行動展現了專業素養。"}]', 'expression'),
('free cash flow', '自由現金流', 'the cash a company generates after accounting for capital expenditures', '[{"en":"Strong free cash flow gives us the flexibility to invest in growth.","zh-TW":"強劲的自由現金流給了我們投資增長的靈活性。"},{"en":"Investors pay close attention to free cash flow as a health indicator.","zh-TW":"投資者密切關注自由現金流作為健康指標。"}]', 'business idiom'),
('fulfill obligations', '履行義務', 'to complete or carry out duties, commitments, or legal requirements', '[{"en":"We fulfilled all obligations under the service agreement on time.","zh-TW":"我們按時履行了服務協議下的所有義務。"},{"en":"Failing to fulfill obligations can result in financial penalties.","zh-TW":"未能履行義務可能導致財務罰款。"}]', 'phrasal verb'),
('gain momentum', '獲得動力；勢頭增強', 'to steadily increase in speed, strength, or support over time', '[{"en":"The product launch gained momentum after early positive reviews.","zh-TW":"早期正面評價後產品上市勢頭增強。"},{"en":"Use early wins to gain momentum for broader adoption.","zh-TW":"利用早期勝利為更廣泛的採用獲得動力。"}]', 'phrasal verb'),
('get to the point', '說重點；直接切入主題', 'to communicate the most important information without unnecessary preamble', '[{"en":"In a 15-minute meeting always get to the point immediately.","zh-TW":"在15分鐘的會議中始終立即說重點。"},{"en":"Executives appreciate emails that get to the point.","zh-TW":"高管欣賞直接切入主題的電子郵件。"}]', 'expression'),
('go-to-market plan', '市場進入計劃；上市策略', 'the strategy for launching a product to the target market effectively', '[{"en":"Our go-to-market plan targeted early adopters in the tech sector.","zh-TW":"我們的市場進入計劃針對了科技行業的早期採用者。"},{"en":"A strong go-to-market plan coordinates sales and marketing.","zh-TW":"強大的上市策略協調了銷售和行銷。"}]', 'business idiom'),
('implementation gap', '執行差距；落實差距', 'the difference between what a strategy intends and what is actually executed', '[{"en":"The implementation gap was caused by unclear ownership of tasks.","zh-TW":"執行差距是由任務所有權不清晰造成的。"},{"en":"Tracking metrics weekly helps close the implementation gap.","zh-TW":"每週跟蹤指標有助於縮小落實差距。"}]', 'business idiom'),
('in parallel', '同時進行；並行', 'at the same time as something else, rather than one after another', '[{"en":"Run testing and documentation in parallel to shorten delivery time.","zh-TW":"同時進行測試和文件編寫以縮短交付時間。"},{"en":"Managing two projects in parallel requires careful coordination.","zh-TW":"並行管理兩個項目需要仔細協調。"}]', 'prepositional phrase'),
('intellectual capital', '智識資本；知識資本', 'the intangible value of a company''s knowledge, expertise, and intellectual assets', '[{"en":"Our intellectual capital is protected through patents and trade secrets.","zh-TW":"我們的知識資本通過專利和商業秘密受到保護。"},{"en":"Investing in talent builds the intellectual capital of the organization.","zh-TW":"投資人才建立了組織的知識資本。"}]', 'business idiom'),
('inventory management', '庫存管理', 'the process of ordering, storing, and controlling goods to meet demand efficiently', '[{"en":"Effective inventory management cuts carrying costs by 20%.","zh-TW":"有效的庫存管理將持有成本降低了20%。"},{"en":"Real-time data improves inventory management accuracy.","zh-TW":"實時數據提高了庫存管理的準確性。"}]', 'business idiom'),
('kickstart', '啟動；推動', 'to cause something to start or be reinvigorated with extra effort or a fresh impetus', '[{"en":"We kickstarted growth by launching a referral incentive program.","zh-TW":"我們通過推出推薦激勵計劃啟動了增長。"},{"en":"The government grant kickstarted the startup''s product development.","zh-TW":"政府補助金推動了初創公司的產品開發。"}]', 'phrasal verb'),
('lean methodology', '精益方法論', 'a management philosophy focused on minimizing waste while maximizing value delivery', '[{"en":"Lean methodology helped us cut production cycle time by 30%.","zh-TW":"精益方法論幫助我們將生產週期時間縮短了30%。"},{"en":"Training staff in lean methodology yields measurable efficiency gains.","zh-TW":"培訓員工掌握精益方法論帶來了可衡量的效率提升。"}]', 'business idiom'),
('line of business', '業務線；業務部門', 'a specific product or service area within a larger organization', '[{"en":"We launched cloud services as a new line of business.","zh-TW":"我們推出了雲服務作為新的業務線。"},{"en":"Each line of business has its own P&L and leadership team.","zh-TW":"每個業務線都有自己的損益表和領導團隊。"}]', 'business idiom'),
('market consolidation', '市場整合', 'the process by which a market becomes dominated by fewer, larger players through mergers and exits', '[{"en":"Market consolidation reduced our main competitors from ten to three.","zh-TW":"市場整合將我們的主要競爭對手從十個減少到三個。"},{"en":"During market consolidation scale becomes a critical advantage.","zh-TW":"在市場整合過程中規模成為關鍵優勢。"}]', 'business idiom'),
('market share gain', '市場份額增長', 'the increase in a company''s portion of total sales within its market', '[{"en":"Our product innovation drove a 5-point market share gain last year.","zh-TW":"我們的產品創新去年推動了5個百分點的市場份額增長。"},{"en":"Aggressive pricing resulted in significant market share gains.","zh-TW":"積極的定價策略帶來了顯著的市場份額增長。"}]', 'business idiom'),
('milestone review', '里程碑評審', 'a formal assessment conducted at each major stage of a project to verify progress', '[{"en":"A milestone review confirmed we were on track for the Q3 launch.","zh-TW":"里程碑評審確認了我們按計劃進行第三季度的上市。"},{"en":"Use milestone reviews to realign if scope has changed.","zh-TW":"如果範圍發生了變化請使用里程碑評審重新調整。"}]', 'business idiom'),
('minimum viable product', '最小可行產品', 'the simplest version of a product that delivers core value and can be tested with users', '[{"en":"We launched a minimum viable product to test demand before full investment.","zh-TW":"我們在全面投資之前推出了最小可行產品測試需求。"},{"en":"A minimum viable product lets you learn without building everything first.","zh-TW":"最小可行產品讓您在不先構建一切的情況下學習。"}]', 'business idiom'),
('mission critical', '關鍵任務；核心關鍵', 'describing a system or component whose failure would halt essential operations', '[{"en":"Backup power is mission critical for our data center.","zh-TW":"備用電源對我們的數據中心至關重要。"},{"en":"Mission critical software requires 99.99% uptime.","zh-TW":"關鍵任務軟體需要99.99%的正常運行時間。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('morale booster', '士氣提振；振奮人心之舉', 'an action, event, or reward that increases motivation and positive energy in a team', '[{"en":"Celebrating small wins is a powerful morale booster.","zh-TW":"慶祝小勝利是強大的士氣提振措施。"},{"en":"A team outing worked as a morale booster after a stressful quarter.","zh-TW":"在壓力大的季度後團隊外出活動起到了振奮人心的作用。"}]', 'expression'),
('onboard a client', '客戶入職；接洽新客戶', 'to guide a new client through the initial setup and orientation to your products or services', '[{"en":"We onboard each new client with a dedicated success manager.","zh-TW":"我們為每個新客戶配備專屬的成功經理進行入職引導。"},{"en":"A smooth onboarding process reduces early churn.","zh-TW":"順暢的客戶入職流程減少了早期流失。"}]', 'phrasal verb'),
('operating leverage', '經營槓桿', 'the degree to which fixed costs amplify profit changes relative to revenue changes', '[{"en":"High operating leverage means profits grow faster than revenue.","zh-TW":"高經營槓桿意味著利潤增長快於收入。"},{"en":"Software companies often have strong operating leverage.","zh-TW":"軟體公司通常具有強大的經營槓桿。"}]', 'business idiom'),
('organic reach', '自然觸及；有機觸及', 'the number of people who see content without paid promotion', '[{"en":"Our organic reach doubled after consistently publishing educational content.","zh-TW":"持續發布教育性內容後我們的自然觸及翻了一番。"},{"en":"Build organic reach before investing heavily in paid advertising.","zh-TW":"在大量投資付費廣告之前先建立有機觸及。"}]', 'business idiom'),
('outcome-based contract', '以結果為基礎的合約', 'an agreement where payment is tied to achieving specific measurable results', '[{"en":"Our outcome-based contract ties fees to measurable KPIs.","zh-TW":"我們以結果為基礎的合約將費用與可衡量的KPI掛鉤。"},{"en":"Outcome-based contracts align vendor incentives with client success.","zh-TW":"以結果為基礎的合約使供應商激勵與客戶成功保持一致。"}]', 'business idiom'),
('payback period', '回收期；投資回收期', 'the time required to recover the cost of an investment from its net cash inflows', '[{"en":"The payback period for the new equipment is 18 months.","zh-TW":"新設備的投資回收期為18個月。"},{"en":"A shorter payback period reduces investment risk.","zh-TW":"較短的回收期降低了投資風險。"}]', 'business idiom'),
('performance appraisal', '績效考核；工作評估', 'a formal evaluation of an employee''s performance, usually conducted annually', '[{"en":"Performance appraisals help align individual goals with company objectives.","zh-TW":"績效考核有助於將個人目標與公司目標保持一致。"},{"en":"Provide specific examples during a performance appraisal.","zh-TW":"在績效考核期間提供具體例子。"}]', 'business idiom'),
('put on the table', '提出；擺上台面', 'to formally introduce or offer something for consideration in a discussion', '[{"en":"We put a 10% discount on the table to close the deal faster.","zh-TW":"我們提出了10%的折扣以更快地達成交易。"},{"en":"All options should be put on the table before a final decision.","zh-TW":"在做出最終決定之前應將所有選項擺上台面。"}]', 'expression'),
('quality assurance', '品質保證', 'systematic processes to ensure products or services meet defined standards', '[{"en":"Quality assurance processes reduced defect rates by 40%.","zh-TW":"品質保證流程將缺陷率降低了40%。"},{"en":"Quality assurance must be built into every stage of development.","zh-TW":"品質保證必須融入開發的每個階段。"}]', 'business idiom'),
('quarterly business review', '季度業務審查', 'a regular meeting where performance, challenges, and plans are reviewed with clients or leadership', '[{"en":"A quarterly business review strengthens the partnership with major clients.","zh-TW":"季度業務審查加強了與主要客戶的合作關係。"},{"en":"Use a quarterly business review to realign on strategic priorities.","zh-TW":"利用季度業務審查重新調整戰略優先事項。"}]', 'business idiom'),
('reduce friction', '減少阻力；降低摩擦', 'to remove barriers or difficulties that slow down a process or user experience', '[{"en":"Simplifying checkout reduced friction and improved conversion.","zh-TW":"簡化結帳減少了阻力並提高了轉化率。"},{"en":"Reduce friction in the onboarding flow to drive faster adoption.","zh-TW":"減少入職流程中的阻力以推動更快的採用。"}]', 'phrasal verb'),
('request for proposal', '建議書邀請；招標書', 'a formal document issued by an organization asking vendors to submit proposals for a service', '[{"en":"We submitted a comprehensive response to the request for proposal.","zh-TW":"我們提交了對建議書邀請的全面回應。"},{"en":"A well-crafted request for proposal attracts higher-quality vendors.","zh-TW":"精心制定的招標書吸引了更高品質的供應商。"}]', 'business idiom'),
('return on equity', '股東權益報酬率', 'a measure of profitability showing how much profit is generated per unit of equity', '[{"en":"Strong return on equity signals effective use of shareholder capital.","zh-TW":"強勁的股東權益報酬率表明股東資本的有效利用。"},{"en":"Investors compare return on equity across competitors to find value.","zh-TW":"投資者比較各競爭對手的股東權益報酬率以尋找價值。"}]', 'business idiom'),
('risk mitigation plan', '風險緩解計劃', 'a strategy for reducing the likelihood or impact of identified risks', '[{"en":"A risk mitigation plan was approved before construction began.","zh-TW":"施工開始之前批准了風險緩解計劃。"},{"en":"Update the risk mitigation plan whenever new threats are identified.","zh-TW":"每當識別出新威脅時更新風險緩解計劃。"}]', 'business idiom'),
('root cause', '根本原因；根源', 'the fundamental underlying reason for a problem rather than its surface symptoms', '[{"en":"We identified the root cause of the defect as inconsistent supplier quality.","zh-TW":"我們將缺陷的根本原因確定為供應商品質不一致。"},{"en":"Fix the root cause, not just the symptoms, of operational problems.","zh-TW":"解決運營問題的根本原因而不僅僅是症狀。"}]', 'business idiom'),
('sales cycle', '銷售週期', 'the series of steps from first contact with a prospect to closing a deal', '[{"en":"A clear ROI case shortens the sales cycle considerably.","zh-TW":"清晰的投資回報案例大大縮短了銷售週期。"},{"en":"Track conversion at every stage of the sales cycle.","zh-TW":"在銷售週期的每個階段跟蹤轉化。"}]', 'business idiom'),
('scale operations', '擴大運營規模；規模化', 'to increase the capacity and reach of a business process to handle more volume', '[{"en":"We scaled operations from 5 to 50 countries in three years.","zh-TW":"我們在三年內將業務規模從5個國家擴展到了50個國家。"},{"en":"Automation is key to scaling operations without proportional cost increases.","zh-TW":"自動化是在不按比例增加成本的情況下規模化運營的關鍵。"}]', 'phrasal verb'),
('secondary market', '二級市場', 'a market where previously issued securities or goods are bought and sold between investors', '[{"en":"The bond rallied in the secondary market after the credit upgrade.","zh-TW":"信用評級上調後債券在二級市場上漲。"},{"en":"Secondary market activity reflects investor confidence in the company.","zh-TW":"二級市場活動反映了投資者對公司的信心。"}]', 'business idiom'),
('segment the market', '細分市場', 'to divide the market into distinct groups with similar characteristics or needs', '[{"en":"We segmented the market by purchase frequency to target high-value customers.","zh-TW":"我們按購買頻率細分市場以針對高價值客戶。"},{"en":"Segmenting the market allows for more personalized marketing.","zh-TW":"細分市場使更個性化的行銷成為可能。"}]', 'phrasal verb'),
('share of wallet', '錢包份額；客戶總消費佔比', 'the percentage of a customer''s total spending in a category that goes to your company', '[{"en":"Cross-selling grew our share of wallet from 20% to 35%.","zh-TW":"交叉銷售使我們的錢包份額從20%增加到了35%。"},{"en":"Focus on share of wallet to grow revenue from existing accounts.","zh-TW":"關注錢包份額以從現有帳戶增加收入。"}]', 'business idiom'),
('stakeholder management', '利害關係人管理', 'the process of identifying and engaging people who are affected by or influence a project', '[{"en":"Effective stakeholder management prevented conflict during the merger.","zh-TW":"有效的利害關係人管理防止了合併期間的衝突。"},{"en":"Map all stakeholders and their influence before the project starts.","zh-TW":"在項目開始之前繪製所有利害關係人及其影響力。"}]', 'business idiom'),
('statement of work', '工作說明書', 'a document describing the scope, deliverables, and timeline for a contracted project', '[{"en":"A clear statement of work prevents scope creep.","zh-TW":"清晰的工作說明書防止了範圍蔓延。"},{"en":"Both parties signed the statement of work before work began.","zh-TW":"雙方在工作開始之前簽署了工作說明書。"}]', 'business idiom'),
('streamline the process', '簡化流程；精簡程序', 'to make a process more efficient by removing unnecessary steps', '[{"en":"We streamlined the approval process from five steps to two.","zh-TW":"我們將審批流程從五個步驟簡化為兩個。"},{"en":"Streamlining the process cut order processing time by half.","zh-TW":"簡化流程將訂單處理時間縮短了一半。"}]', 'phrasal verb'),
('technical debt', '技術債；技術欠債', 'the cost of future rework caused by taking shortcuts in software development', '[{"en":"Accumulating technical debt slows down future feature development.","zh-TW":"積累技術債會減慢未來功能開發速度。"},{"en":"Allocate 20% of each sprint to reducing technical debt.","zh-TW":"分配每個衝刺20%的時間來減少技術債。"}]', 'business idiom'),
('total cost of ownership', '總擁有成本', 'all direct and indirect costs incurred over the entire lifecycle of an asset or service', '[{"en":"Total cost of ownership analysis showed the cheaper option was more expensive long-term.","zh-TW":"總擁有成本分析顯示較便宜的選項長期來看更貴。"},{"en":"Always present total cost of ownership when evaluating vendor proposals.","zh-TW":"評估供應商提案時始終呈現總擁有成本。"}]', 'business idiom'),
('upsell opportunity', '追加銷售機會；升級銷售機會', 'a chance to persuade an existing customer to buy a higher-value product or service', '[{"en":"The annual review uncovered several upsell opportunities.","zh-TW":"年度評審發現了幾個追加銷售機會。"},{"en":"Train support staff to recognize upsell opportunities.","zh-TW":"培訓支持人員識別升級銷售機會。"}]', 'business idiom'),
('upward mobility', '向上流動；晉升機會', 'the ability to advance to higher positions or greater success in a career or organization', '[{"en":"Clear career paths and upward mobility reduce staff turnover.","zh-TW":"清晰的職業路徑和晉升機會減少了員工流失。"},{"en":"Promote upward mobility to create a high-performance culture.","zh-TW":"促進向上流動以創建高績效文化。"}]', 'expression'),
('user-centric design', '以用戶為中心的設計', 'a design philosophy that prioritizes the needs, preferences, and behaviors of end users', '[{"en":"User-centric design led to a 50% increase in app engagement.","zh-TW":"以用戶為中心的設計使應用程式參與度提高了50%。"},{"en":"Interview real users before finalizing user-centric design decisions.","zh-TW":"在最終確定以用戶為中心的設計決策之前採訪真實用戶。"}]', 'business idiom'),
('value-added service', '增值服務', 'an extra service provided beyond the core offering to increase its value to the customer', '[{"en":"Free training is a value-added service that increases retention.","zh-TW":"免費培訓是增加留存率的增值服務。"},{"en":"Bundle value-added services to justify a premium price.","zh-TW":"捆綁增值服務以證明溢價的合理性。"}]', 'business idiom'),
('vendor evaluation', '供應商評估', 'the process of assessing suppliers against defined criteria before selection or renewal', '[{"en":"Vendor evaluation includes financial stability, capacity, and quality metrics.","zh-TW":"供應商評估包括財務穩定性、產能和品質指標。"},{"en":"Run a vendor evaluation annually to ensure continued performance.","zh-TW":"每年進行供應商評估以確保持續的績效。"}]', 'business idiom'),
('workforce planning', '人力規劃；人力資源規劃', 'the strategic process of aligning workforce capacity with current and future business needs', '[{"en":"Workforce planning identified a critical shortage in data engineering.","zh-TW":"人力規劃確定了數據工程的嚴重短缺。"},{"en":"Use workforce planning to anticipate hiring needs 12 months ahead.","zh-TW":"使用人力規劃提前12個月預測招聘需求。"}]', 'business idiom'),
('year-end review', '年終回顧；年末盤點', 'a comprehensive assessment of performance, achievements, and challenges at the end of a fiscal year', '[{"en":"The year-end review highlighted our strongest performing product lines.","zh-TW":"年終回顧突出了我們表現最好的產品線。"},{"en":"Use the year-end review to celebrate wins and set next year''s goals.","zh-TW":"利用年末盤點慶祝勝利並設定明年的目標。"}]', 'expression'),
('zero defects', '零缺陷', 'a quality management goal of eliminating all defects from production or service delivery', '[{"en":"Our zero defects policy raised customer satisfaction scores significantly.","zh-TW":"我們的零缺陷政策顯著提高了客戶滿意度分數。"},{"en":"Zero defects requires continuous process monitoring and improvement.","zh-TW":"零缺陷需要持續的過程監控和改進。"}]', 'business idiom'),
('zone in on', '聚焦於；集中關注', 'to direct one''s focus to a specific area or detail', '[{"en":"Zone in on the top three revenue drivers for this quarter.","zh-TW":"聚焦於本季度前三大收入驅動因素。"},{"en":"During the meeting zone in on decisions that need immediate resolution.","zh-TW":"在會議期間集中關注需要立即解決的決定。"}]', 'phrasal verb'),
('above the fold', '首屏位置；頭版顯眼位置', 'the portion of a webpage or document visible without scrolling; the most prominent position', '[{"en":"Put the call-to-action above the fold for maximum visibility.","zh-TW":"將行動號召放在首屏位置以獲得最大曝光。"},{"en":"Above-the-fold placement commands a premium in digital advertising.","zh-TW":"首屏位置在數位廣告中需要溢價。"}]', 'expression'),
('accounts payable', '應付帳款', 'money owed by a company to its suppliers for goods or services received but not yet paid', '[{"en":"Optimizing accounts payable extended our payment cycle by 15 days.","zh-TW":"優化應付帳款將我們的付款週期延長了15天。"},{"en":"Accounts payable automation reduces manual processing errors.","zh-TW":"應付帳款自動化減少了手動處理錯誤。"}]', 'business idiom'),
('accounts receivable', '應收帳款', 'money owed to a company by its customers for goods or services delivered but not yet paid', '[{"en":"Slow accounts receivable collection hurt our working capital.","zh-TW":"緩慢的應收帳款收款損害了我們的營運資金。"},{"en":"We offer early payment discounts to accelerate accounts receivable.","zh-TW":"我們提供提前付款折扣以加速應收帳款回收。"}]', 'business idiom'),
('adopt a framework', '採用框架；應用方法論', 'to implement a structured approach or system for solving problems or making decisions', '[{"en":"We adopted an OKR framework to align goals across the company.","zh-TW":"我們採用了OKR框架來對齊公司各層級的目標。"},{"en":"Adopting a risk framework improved our project governance.","zh-TW":"採用風險框架改善了我們的項目治理。"}]', 'phrasal verb'),
('all-in cost', '全包成本；總成本', 'the complete cost including all fees, overhead, and hidden charges', '[{"en":"The all-in cost of hiring includes salary, benefits, and onboarding.","zh-TW":"招聘的全包成本包括薪資、福利和入職培訓。"},{"en":"Present the all-in cost so clients are not surprised later.","zh-TW":"呈現全包成本讓客戶之後不會感到意外。"}]', 'business idiom'),
('annual recurring revenue', '年度經常性收入', 'the predictable revenue a business expects to receive each year from subscriptions or contracts', '[{"en":"Annual recurring revenue grew 40% after improving the subscription model.","zh-TW":"改善訂閱模式後年度經常性收入增長了40%。"},{"en":"Annual recurring revenue is a key SaaS health metric.","zh-TW":"年度經常性收入是SaaS健康狀況的關鍵指標。"}]', 'business idiom'),
('approval workflow', '審批流程；批核工作流程', 'the defined sequence of review and sign-off steps required to complete an action', '[{"en":"Automating the approval workflow reduced cycle time from days to hours.","zh-TW":"自動化審批流程將週期時間從幾天縮短到了幾個小時。"},{"en":"A clear approval workflow avoids ambiguity about who decides.","zh-TW":"清晰的審批流程避免了關於誰決策的模糊性。"}]', 'business idiom'),
('asset utilization', '資產利用率', 'a measure of how efficiently a company uses its assets to generate revenue', '[{"en":"Asset utilization improved after we switched to a shared equipment model.","zh-TW":"轉向共享設備模式後資產利用率提高了。"},{"en":"Track asset utilization monthly to identify inefficiencies.","zh-TW":"每月跟蹤資產利用率以識別低效率。"}]', 'business idiom'),
('balanced scorecard', '平衡計分卡', 'a strategic management tool measuring performance across financial, customer, process, and learning dimensions', '[{"en":"The balanced scorecard gave a holistic view of organizational health.","zh-TW":"平衡計分卡提供了組織健康狀況的全面視角。"},{"en":"Align KPIs to each dimension of the balanced scorecard.","zh-TW":"將KPI與平衡計分卡的每個維度對齊。"}]', 'business idiom'),
('bandwidth constraints', '資源限制；容量限制', 'limits on the time, energy, or people available to take on additional work', '[{"en":"Bandwidth constraints forced us to delay two initiatives.","zh-TW":"資源限制迫使我們推遲了兩個舉措。"},{"en":"Be transparent about bandwidth constraints when accepting new projects.","zh-TW":"在接受新項目時對資源限制保持透明。"}]', 'expression'),
('be on the same page', '意見一致；達成共識', 'to have the same understanding or agreement as others in a group', '[{"en":"Before starting the project we need to be on the same page about scope.","zh-TW":"在開始項目之前我們需要就範圍達成共識。"},{"en":"A kick-off call ensures all teams are on the same page.","zh-TW":"啟動電話確保所有團隊意見一致。"}]', 'expression'),
('below budget', '低於預算；節省開支', 'spending less than the amount allocated for a task or project', '[{"en":"The construction project came in 8% below budget.","zh-TW":"建設項目比預算低了8%。"},{"en":"Finishing below budget earned the team a performance bonus.","zh-TW":"低於預算完成為團隊贏得了績效獎金。"}]', 'prepositional phrase'),
('brand architecture', '品牌架構', 'the organized structure of a company''s brand portfolio and how they relate to each other', '[{"en":"A clear brand architecture reduces customer confusion in the market.","zh-TW":"清晰的品牌架構減少了市場上的客戶困惑。"},{"en":"After the merger we redesigned the brand architecture for clarity.","zh-TW":"合並後我們重新設計了品牌架構以提高清晰度。"}]', 'business idiom'),
('build a case', '建立論據；積累佐證', 'to gather evidence and arguments to support a proposal or decision', '[{"en":"Build a case with data before requesting additional headcount.","zh-TW":"在申請增加人手之前用數據建立論據。"},{"en":"A well-built case speeds up executive approval.","zh-TW":"充分的論據加速了高管批准。"}]', 'expression'),
('business acumen', '商業敏銳度；商業頭腦', 'a keen understanding of business principles and the ability to make sound commercial decisions', '[{"en":"Strong business acumen distinguishes great leaders from good managers.","zh-TW":"強大的商業敏銳度將優秀領導者與優秀管理者區分開來。"},{"en":"Develop business acumen by studying P&L statements and strategy cases.","zh-TW":"通過研究損益表和戰略案例培養商業頭腦。"}]', 'expression'),
('business intelligence', '商業智能', 'data analysis tools and processes that help organizations make better decisions', '[{"en":"Business intelligence dashboards give leadership real-time visibility.","zh-TW":"商業智能儀表板為領導層提供了實時可見度。"},{"en":"Investing in business intelligence paid off with faster and better decisions.","zh-TW":"投資商業智能帶來了更快更好的決策回報。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('C-suite buy-in', '高管層認可；執行委員會支持', 'agreement and support from the highest executives in an organization', '[{"en":"C-suite buy-in is essential for any large-scale transformation.","zh-TW":"C-suite buy-in對任何大規模轉型都是必不可少的。"},{"en":"Present the business case in financial terms to gain C-suite buy-in.","zh-TW":"以財務術語呈現業務案例以獲得高管層認可。"}]', 'expression'),
('call to action', '行動號召', 'a prompt that encourages an audience to take a specific next step', '[{"en":"Every email campaign should have a single clear call to action.","zh-TW":"每個電子郵件活動都應該有一個清晰的行動號召。"},{"en":"A compelling call to action increased our click-through rate by 35%.","zh-TW":"引人注目的行動號召使我們的點擊率提高了35%。"}]', 'expression'),
('capital allocation', '資本分配', 'the process of deciding where to invest or deploy available financial resources', '[{"en":"Disciplined capital allocation is a hallmark of great management teams.","zh-TW":"嚴格的資本分配是優秀管理團隊的標誌。"},{"en":"Review capital allocation annually against strategic priorities.","zh-TW":"每年根據戰略優先事項審查資本分配。"}]', 'business idiom'),
('cash conversion cycle', '現金轉換週期', 'the number of days it takes to convert investments in inventory into cash from sales', '[{"en":"Improving collections reduced our cash conversion cycle by 10 days.","zh-TW":"改善收款將我們的現金轉換週期縮短了10天。"},{"en":"A short cash conversion cycle improves liquidity and financial health.","zh-TW":"較短的現金轉換週期改善了流動性和財務健康。"}]', 'business idiom'),
('client retention', '客戶留存；留住客戶', 'the ability to keep existing customers and prevent them from switching to competitors', '[{"en":"Client retention is five times cheaper than acquiring new customers.","zh-TW":"留住客戶比獲取新客戶便宜五倍。"},{"en":"We measure client retention rate quarterly across all segments.","zh-TW":"我們每季度按所有細分市場衡量客戶留存率。"}]', 'business idiom'),
('consolidate gains', '鞏固成果；穩固優勢', 'to secure and build on progress already made before advancing further', '[{"en":"Consolidate gains from the first quarter before entering new markets.","zh-TW":"在進入新市場之前鞏固第一季度的成果。"},{"en":"Strong teams consolidate gains quickly and are ready for the next challenge.","zh-TW":"強大的團隊迅速鞏固成果並為下一個挑戰做好準備。"}]', 'phrasal verb'),
('contact person', '聯絡人；窗口人員', 'the specific individual responsible for handling communication on a matter', '[{"en":"Please direct all enquiries to your designated contact person.","zh-TW":"請將所有詢問轉交給您指定的聯絡人。"},{"en":"Having a single contact person reduces confusion in client relationships.","zh-TW":"擁有單一聯絡人減少了客戶關係中的混亂。"}]', 'business idiom'),
('content marketing', '內容行銷', 'a strategy of creating valuable content to attract and engage a target audience', '[{"en":"Content marketing generated 60% of our inbound leads last year.","zh-TW":"內容行銷去年為我們帶來了60%的入站潛在客戶。"},{"en":"Great content marketing educates buyers before they contact sales.","zh-TW":"出色的內容行銷在買家聯繫銷售之前就教育了他們。"}]', 'business idiom'),
('data-driven decision', '數據驅動的決策', 'a choice made based on analysis of data rather than intuition or anecdote', '[{"en":"Data-driven decisions reduced our product return rate by 18%.","zh-TW":"數據驅動的決策將我們的產品退貨率降低了18%。"},{"en":"Build a culture of data-driven decisions to stay competitive.","zh-TW":"建立數據驅動決策的文化以保持競爭力。"}]', 'business idiom'),
('dynamic pricing', '動態定價', 'a pricing strategy where prices are adjusted in real time based on demand and other factors', '[{"en":"Dynamic pricing increased revenue per seat on high-demand routes.","zh-TW":"動態定價增加了高需求航線的每座收入。"},{"en":"Be transparent about dynamic pricing to maintain customer trust.","zh-TW":"對動態定價保持透明以維護客戶信任。"}]', 'business idiom'),
('ecosystem play', '生態系統策略；平台生態佈局', 'a strategy of building or joining a network of complementary products and partners', '[{"en":"The ecosystem play attracted 200 partner integrations in one year.","zh-TW":"生態系統策略在一年內吸引了200個合作夥伴整合。"},{"en":"An ecosystem play makes it harder for customers to switch.","zh-TW":"生態系統佈局使客戶更難以轉換。"}]', 'business idiom');
INSERT INTO grammar_topics (id, title, category, level, explanation_md) VALUES
(1, 'Present Simple vs Present Continuous', 'tense', 2, '現在簡單式用於習慣或事實（She works every day），現在進行式用於當下正在發生的動作（She is working now）。靜態動詞如 know、believe 不用進行式。商業英語中，簡單式描述職責，進行式描述當前專案。'),
(2, 'Past Simple vs Past Continuous', 'tense', 2, '過去簡單式描述已完成的過去動作，過去進行式描述過去某時刻正在進行的動作。兩者常搭配：進行式為背景，簡單式為插入動作。'),
(3, 'Present Perfect', 'tense', 3, '現在完成式（have/has + 過去分詞）連結過去動作與現在結果，常與 just、already、yet、ever、never、since、for 連用，不與 yesterday、last year 等明確過去時間連用。'),
(4, 'Present Perfect vs Past Simple', 'tense', 3, '現在完成式強調對現在的影響；過去簡單式描述已結束的特定事件。ago/yesterday/last year → 過去式；already/yet/just/since/for → 完成式。'),
(5, 'Past Perfect', 'tense', 3, '過去完成式（had + 過去分詞）描述過去某時間點之前已完成的動作，建立兩個過去事件的先後順序，常與 before、by the time、when、already 等連用。'),
(6, 'Future: will vs going to', 'tense', 2, 'will 用於臨時決定、承諾或預測；be going to 用於已計劃的意圖或根據證據的預測。兩者均可表未來，but 語用不同。'),
(7, 'Future Perfect and Future Continuous', 'tense', 4, '未來完成式（will have + p.p.）表示到未來某點前將完成的動作；未來進行式（will be + V-ing）表示未來某時刻正在進行的動作。兩者常用於商業時程規劃。'),
(8, 'Mixed Tenses', 'tense', 4, '混合時態練習要求根據語境選擇正確時態，是商業英語的重要能力。正確選擇時態能清楚傳達事件的時間順序和因果關係。'),
(9, 'Definite Article: the', 'article', 2, '定冠詞 the 用於雙方均知的特定事物、再次提及、獨一無二的事物及最高級前。商業英語中常見於職稱（the CEO）、特定文件（the report）、最高級（the best）。'),
(10, 'Indefinite Articles: a / an', 'article', 1, '不定冠詞 a 用在輔音音素前，an 用在母音音素前。注意判斷依據是發音不是拼字（如 an hour、an MBA）。用於首次提及或泛指某類別。'),
(11, 'Zero Article', 'article', 3, '零冠詞（不加冠詞）用於複數可數名詞泛稱、不可數名詞泛稱、專有名詞、及 go to work/by email 等固定搭配。避免在泛稱前加 the。'),
(12, 'Prepositions of Time: at/in/on', 'preposition', 2, 'at 用於精確時間（at 3 p.m.）；in 用於較長時段（in March、in 2024）；on 用於特定日期和星期（on Monday、on January 5th）。商業場合中正確使用避免誤解。'),
(13, 'Prepositions of Place: at/in/on', 'preposition', 2, 'at 表精確地點或功能性場所（at the reception）；in 表有邊界空間或地區（in the office）；on 表面或樓層（on the desk、on the third floor）。'),
(14, 'Prepositions of Movement', 'preposition', 2, '移動介系詞描述從一地到另一地的動作：to（去到）、into（進入）、out of（出去）、through（穿過）、across（橫越）、along（沿著）、past（經過）。'),
(15, 'Dependent Prepositions (adjective + prep)', 'preposition', 3, '形容詞與特定介系詞的固定搭配，如 responsible for、interested in、satisfied with、familiar with。必須記憶，不可任意替換。'),
(16, 'Dependent Prepositions (verb + prep)', 'preposition', 3, '動詞與特定介系詞的固定搭配，如 apply for、deal with、rely on、invest in。錯誤使用介系詞會造成誤解，需熟記常見搭配。'),
(17, 'Zero and First Conditional', 'conditional', 2, '零條件句（if + 現在式，現在式）表普遍事實；第一條件句（if + 現在式，will）表真實可能的未來情況。商業英語常用第一條件句提案或預測。'),
(18, 'Second Conditional', 'conditional', 3, '第二條件句（if + 過去式，would）表示假設或不太可能的情況。注意 if 子句中 be 動詞正式英語用 were，常用於假設討論和商業頭腦風暴。'),
(19, 'Third Conditional', 'conditional', 4, '第三條件句（if + had + p.p.，would have + p.p.）描述過去假設，用於反思決策。商業案例分析和後見之明討論中常見。'),
(20, 'Mixed Conditionals', 'conditional', 5, '混合條件句結合不同時態：最常見是 if + 過去完成式（過去假設），would + 原形（現在結果），如 If I had taken that job, I would be in London now。'),
(21, 'Modal: can / could', 'modal', 2, 'can 表現在的能力、許可或可能性；could 表過去能力、假設可能性或禮貌請求。商業英語中 could 比 can 更正式有禮貌。'),
(22, 'Modal: must / have to', 'modal', 2, 'must 表主觀強烈義務或邏輯推論；have to 表外在客觀規定。must not 表禁止；do not have to 表不必要（不是禁止）。'),
(23, 'Modal: should / ought to', 'modal', 2, 'should 和 ought to 表建議或期望，should 更口語常用。商業英語中 should 常見於建議、指南、政策手冊中。'),
(24, 'Modal: may / might', 'modal', 3, 'may 和 might 都表可能性，might 確定性略低。may 也可表正式許可。商業報告中用於謹慎預測，避免過於武斷。'),
(25, 'Modal: would', 'modal', 3, 'would 多用法：過去習慣、禮貌請求（Would you...）、假設（I would accept）、提供建議（I would recommend）。商業溝通中是最禮貌的情態動詞。'),
(26, 'Modal Perfect: should have / could have / would have', 'modal', 4, '情態完成式談論過去不同的可能：should have（應該做但沒做，遺憾/批評），could have（本可以，可能性），would have（假設結果）。'),
(27, 'Passive Voice: Simple Tenses', 'passive', 3, '被動語態（am/is/are/was/were + p.p.）強調動作接受者，廣泛用於商業正式文件。當行為者不重要或不明確時特別適用。'),
(28, 'Passive Voice: Perfect Tenses', 'passive', 4, '完成被動式：現在完成被動（have/has been + p.p.）和過去完成被動（had been + p.p.）。商業報告中用於說明已完成的程序，語氣正式客觀。'),
(29, 'Passive Voice: Modal Verbs', 'passive', 4, '情態被動（modal + be + p.p.）廣泛用於商業政策和通知：must be submitted、should be reviewed、will be sent、can be accessed。'),
(30, 'Causative Have/Get', 'passive', 4, '使役結構：have/get something done（安排別人做）；have someone do（主動命令）；get someone to do（說服/促使）。常用於委託、外包描述。'),
(31, 'Reported Speech: Statements', 'reported speech', 3, '間接引語將直接引語轉為第三人稱，動詞時態後移，代名詞和時間副詞也需調整。商業會議記錄和轉述客戶意見時常用。'),
(32, 'Reported Speech: Questions', 'reported speech', 3, '間接問句語序是陳述句序，no 不用問號。yes/no 問句用 if/whether 引導。如：She asked what the deadline was；He asked if the report was ready。'),
(33, 'Reported Speech: Commands', 'reported speech', 3, '間接命令句：tell/ask/order/advise + 受詞 + to do（肯定）；tell + 受詞 + not to do（否定）。'),
(34, 'Backshift in Reported Speech', 'reported speech', 4, '間接引語時態後移規則：現在→過去，過去→過去完成，will→would，can→could，may→might。時間副詞：now→then，today→that day，tomorrow→the following day，here→there。'),
(35, 'Defining Relative Clauses', 'relative clause', 3, '限定性關係子句提供識別被修飾名詞所必需的資訊，不用逗號，可用 who（人）、which（物）、that（人或物）、whose（所有格）。'),
(36, 'Non-defining Relative Clauses', 'relative clause', 4, '非限定性關係子句提供額外（非必要）資訊，用逗號隔開，不可用 that，只用 who/which/whose/where/when。'),
(37, 'Relative Pronouns: who/which/that/whose', 'relative clause', 3, 'who 指人（主格/受格），which 指物（限定/非限定），that 指人或物（只限限定子句），whose 表所有格（人或物）。'),
(38, 'Gerund vs Infinitive after Verbs', 'gerund/infinitive', 3, '某些動詞後接動名詞（enjoy/finish/suggest/consider/avoid），某些後接不定詞（want/decide/agree/plan/refuse），有些兩者皆可但意思可能不同（stop/remember/try）。'),
(39, 'Gerund as Subject', 'gerund/infinitive', 2, '動名詞可作句子主語，如 Managing a team requires strong communication skills。這種結構在商業政策說明、工作描述中非常常見。'),
(40, 'Infinitive of Purpose', 'gerund/infinitive', 2, '不定詞表目的（to do），更正式用 in order to 或 so as to。商業英語中清楚說明行動目的，常見於策略計劃和提案。'),
(41, 'Verb + Object + Infinitive', 'gerund/infinitive', 3, '某些動詞後接受詞再接不定詞：want/ask/advise/require/expect/allow/encourage + 受詞 + to do。商業指示和委託中大量使用。'),
(42, 'Comparative Adjectives', 'comparison', 2, '比較級：單音節 + -er（faster）；多音節 + more（more efficient）；不規則：good→better，bad→worse，far→farther/further。'),
(43, 'Superlative Adjectives', 'comparison', 2, '最高級：單音節 + the -est（the fastest）；多音節 + the most（the most innovative）；不規則：good→the best，bad→the worst。'),
(44, 'Comparing with as...as', 'comparison', 2, 'as + 形容詞/副詞 + as 表相等；not as...as 表不如；the same...as 表相同；as much/many...as 表數量相等。'),
(45, 'Double Comparatives', 'comparison', 4, '雙重比較結構 the + 比較級 + the + 比較級，表示正比或反比關係。常見於商業策略討論，如 The more we invest, the higher the returns。'),
(46, 'Adverbial Clauses of Time', 'clause', 3, '時間副詞子句由 when、while、as soon as、before、after、until、by the time 等引導，表示動作發生的時間關係。'),
(47, 'Adverbial Clauses of Reason', 'clause', 3, '原因副詞子句由 because、since、as、now that 等引導，解釋動作的原因。商業英語中常用於說明決策理由。'),
(48, 'Adverbial Clauses of Contrast', 'clause', 3, '對比副詞子句由 although、even though、while、whereas 等引導，承認一個事實同時提出相反情況。商業英語中用於客觀分析。'),
(49, 'Adverbial Clauses of Result', 'clause', 3, '結果副詞子句由 so...that 或 such...that 引導，表示原因導致的結果。如 The presentation was so compelling that the client signed immediately。'),
(50, 'Noun Clauses', 'clause', 4, '名詞子句充當名詞功能（主語、受語或補語），常由 that、whether、what、how、why、who 等引導。商業英語中常用於表達觀點和轉述資訊。');